testo:
{
 "genere": "obiettivo",
 "titolo": "Mostra la versione del gioco nel menu",
 "consegna": "Aggiungi l'indicazione della versione del gioco nel menu principale del Quiz (`menu.tscn`).\n\n1. In `quiz_data.gd` definisci la costante `GAME_VERSION` con valore `\"v1.0.0\"`.\n2. Nel menu principale (`menu.tscn`) aggiungi un `Label` chiamato `VersionLabel`.\n3. All'avvio del menu, `VersionLabel` deve mostrare la versione definita in `QuizData.GAME_VERSION` (`\"v1.0.0\"`).",
 "modalita": "progetto",
 "dove": "gioco",
 "cartella": "quiz",
 "passiGuida": [],
 "suggerimenti": [
  "Puoi accedere alla costante dichiarata nell'Autoload scrivendo `QuizData.GAME_VERSION` dentro lo script `menu.gd`."
 ],
 "verifiche": [
  {
   "tipo": "testo_in_file",
   "percorso": "res://quiz_data.gd",
   "regex": "const GAME_VERSION",
   "descrizione": "Lo script quiz_data.gd definisce la costante GAME_VERSION"
  },
  {
   "tipo": "nodo",
   "scena": "res://menu.tscn",
   "tipoNodo": "Label",
   "nome": "VersionLabel",
   "descrizione": "La scena menu.tscn contiene un Label chiamato VersionLabel"
  },
  {
   "tipo": "script_godot",
   "descrizione": "All'avvio del menu, VersionLabel mostra la versione presa da QuizData.GAME_VERSION",
   "codice": "extends \"res://htd/htd_test.gd\"\n\n\nfunc _run_tests() -> void:\n\tvar menu := await instantiate_scene(\"res://menu.tscn\")\n\tif not check(\"menu\", menu != null, \"La scena menu.tscn deve caricarsi senza errori\"):\n\t\treturn\n\tvar label := find_by_name(menu, \"VersionLabel\") as Label\n\tif not check(\"version_label\", label != null, \"La scena menu.tscn deve contenere un Label chiamato VersionLabel\"):\n\t\treturn\n\tcheck(\"label_text\", label.text == \"v1.0.0\", \"Il testo di VersionLabel deve essere 'v1.0.0' (trovato: '%s')\" % label.text)\n"
  }
 ],
 "soluzione": {
  "progetto": {
   "nome": "Quiz",
   "scenaPrincipale": "res://menu.tscn",
   "azioni": [
    {
     "nome": "pause",
     "tasti": [
      "Escape"
     ]
    }
   ],
   "autoload": [
    {
     "nome": "QuizData",
     "percorso": "res://quiz_data.gd"
    }
   ],
   "impostazioni": [
    {
     "sezione": "display",
     "chiave": "window/stretch/mode",
     "valore": "canvas_items"
    },
    {
     "sezione": "display",
     "chiave": "window/stretch/aspect",
     "valore": "expand"
    },
    {
     "sezione": "display",
     "chiave": "window/size/viewport_width",
     "valore": "1152"
    },
    {
     "sezione": "display",
     "chiave": "window/size/viewport_height",
     "valore": "648"
    }
   ]
  },
  "file": [
   {
    "percorso": "quiz_data.gd",
    "contenuto": "extends Node\n\nconst GAME_VERSION: String = \"v1.0.0\"\n\nvar score: int = 0\nvar high_score: int = 0\nvar current_topic_title: String = \"\"\nvar topic_records: Dictionary = {}\n"
   },
   {
    "percorso": "menu.tscn",
    "contenuto": "[gd_scene format=3]\n\n[ext_resource type=\"Script\" path=\"res://menu.gd\" id=\"1_menu\"]\n\n[node name=\"Menu\" type=\"Control\"]\nlayout_mode = 3\nanchors_preset = 15\nanchor_right = 1.0\nanchor_bottom = 1.0\ngrow_horizontal = 2\ngrow_vertical = 2\nscript = ExtResource(\"1_menu\")\n\n[node name=\"TitleLabel\" type=\"Label\" parent=\"..\"]\nlayout_mode = 1\nanchors_preset = 8\nanchor_left = 0.5\nanchor_top = 0.5\nanchor_right = 0.5\nanchor_bottom = 0.5\noffset_left = -100.0\noffset_top = -40.0\noffset_right = 100.0\noffset_bottom = 0.0\ngrow_horizontal = 2\ngrow_vertical = 2\ntext = \"IL QUIZ\"\nhorizontal_alignment = 1\n\n[node name=\"VersionLabel\" type=\"Label\" parent=\"..\"]\nlayout_mode = 1\nanchors_preset = 7\nanchor_left = 0.5\nanchor_top = 1.0\nanchor_right = 0.5\nanchor_bottom = 1.0\noffset_left = -100.0\noffset_top = -50.0\noffset_right = 100.0\noffset_bottom = -20.0\ngrow_horizontal = 2\ngrow_vertical = 0\ntext = \"v1.0.0\"\nhorizontal_alignment = 1\n"
   },
   {
    "percorso": "menu.gd",
    "contenuto": "extends Control\n\n@onready var version_label: Label = $VersionLabel\n\n\nfunc _ready() -> void:\n\tversion_label.text = QuizData.GAME_VERSION\n"
   }
  ],
  "spiegazione": "In Godot, definire una costante per la versione del gioco in uno script Autoload (come `QuizData.GAME_VERSION`) permette di centralizzare la gestione della versione del progetto e di mostrarla facilmente nelle schermate di gioco, ad esempio assegnando il valore a un `Label` nel menu principale all'avvio."
 }
}
